      if (subBess) subBess.className = (mode === "bess") ? "text-[10px] font-medium text-blue-100" : "text-[10px] font-medium text-slate-500";
      if (subHybrid) subHybrid.className = (mode === "solar_bess") ? "text-[10px] font-medium text-blue-100" : "text-[10px] font-medium text-slate-500";

