    function syncOblenergoOptions() {
      const vKv = state.connectionVoltageKv;
      const vClass = getVoltageClass(vKv);
      const sel = document.getElementById("selOblenergo");
      if (!sel) return;
      const lbl = document.getElementById("lblOblenergoClass");
      if (lbl) {
        lbl.textContent = `Оператор системи розподілу (ОСР, ${vClass} клас — ${vClass === 1 ? '35 кВ' : '6 / 10 кВ'})`;
      }

      let targetIdx = (state.selectedOblenergoIdx >= 0 && state.selectedOblenergoIdx < OBLENERGO_TARIFFS.length)
        ? state.selectedOblenergoIdx
        : 0;

      sel.innerHTML = "";
      OBLENERGO_TARIFFS.forEach((osr, i) => {
        const tariff = (vClass === 1) ? osr.t1 : osr.t2;
        const opt = document.createElement("option");
        opt.value = tariff.toFixed(2);
        opt.textContent = `${osr.name} — ${formatNum(tariff, 2)} грн/МВт·год`;
        if (i === targetIdx) opt.selected = true;
        sel.appendChild(opt);
      });
      const customOpt = document.createElement("option");
      customOpt.value = "custom";
      customOpt.textContent = "Власне значення тарифу розподілу...";
      sel.appendChild(customOpt);

      const activeTariff = (vClass === 1) ? OBLENERGO_TARIFFS[targetIdx].t1 : OBLENERGO_TARIFFS[targetIdx].t2;
      state.distTariff = activeTariff;
      const inpDist = document.getElementById("inpDistTariff");
      if (inpDist) inpDist.value = activeTariff.toFixed(2);
    }

    function getSelectedOblenergoName() {
      const sel = document.getElementById("selOblenergo");
      if (!sel || !sel.options || !sel.options[sel.selectedIndex]) return "ПрАТ «ДТЕК Київські регіональні електромережі»";
      const opt = sel.options[sel.selectedIndex];
      const txt = opt ? (opt.text || opt.textContent || "") : "";
      return txt ? txt.split("—")[0].trim() : "ОСР";
    }

