      const activeTblIdx = (activeEl && activeEl.classList && activeEl.classList.contains("tbl-input-val")) ? activeEl.getAttribute("data-idx") : null;
      const activeTblField = (activeEl && activeEl.classList && activeEl.classList.contains("tbl-input-val")) ? activeEl.getAttribute("data-field") : null;
      let selStart = null;
