      const focusIdx = Math.min(state.chartFocusIdx || 0, Math.max(0, state.configs.length - 1));
      const focusCfg = state.configs[focusIdx] || state.configs[0];
      const sim = runUnifiedHourlySimulation8760(focusCfg);
      const balance = sim.solarBal;
