    function applyInsolationToMonths(insolationVal, showNotification = true) {
      state.solarInsolation = Math.max(100, parseFloat(insolationVal) || 1050);
      const normPerKwp1050 = {
        1: 20.8, 2: 40.0, 3: 79.2, 4: 112.5, 5: 145.8, 6: 154.2,
        7: 158.3, 8: 137.5, 9: 100.0, 10: 54.2, 11: 29.2, 12: 18.3
      };
      const dcKw = state.solarDcKw || 1200;
      const orientFactor = (state.solarOrientation === "east_west") ? 0.91 : 1.0;
      const tiltVal = state.solarTiltAngle !== undefined ? state.solarTiltAngle : 25;
      const tiltFactor = Math.max(0.86, 1.0 - Math.pow((tiltVal - 30) / 60, 2) * 0.15);
      const factor = (state.solarInsolation / 1050.0) * orientFactor * tiltFactor;

      state.enterpriseMonths.forEach((mObj) => {
        const norm = (normPerKwp1050[mObj.month] || 87.5) * factor;
        mObj.solarKwh = Math.round(dcKw * norm);
      });
      _hourlyDatasetCache = null;
      _hourlySimCache.clear();
      renderSolarAndLoadSection();
      recalculateAll(false);
      if (showNotification) {
        showToast(`Розраховано генерацію 12 міс. (${formatNum(state.solarInsolation, 0)} кВт·год/кВт • ${state.solarOrientation === "east_west" ? "Схід-Захід" : "Південь"} • ${tiltVal}°)`);
      }
    }

    function evaluateConfig(cfg) {
      const currMeta = getCurrencyMeta();
      const rateToUah = currMeta.rateToUah || 41.5;
      const disc = (state.discountRate || 10) / 100;
      const deg = (state.degradPct || 2.0) / 100;

      const sim = runUnifiedHourlySimulation8760(cfg);
      const legacy = runLegacyAveragedModel(cfg);
      const solarBal = sim.solarBal;

      const solarCapexTotal = state.hasSolar && state.projectConfigMode !== "bess"
        ? Math.round((state.solarDcKw || 0) * (state.solarCapexPerKw || 0))
        : 0;
      const solarOpexAnnualUsd = solarCapexTotal * ((state.solarOpexPct !== undefined ? state.solarOpexPct : 1.0) / 100);

      // Compute LCOE of Solar (10-year discounted lifecycle cost / 10-year discounted kWh)
      let lcoeSolarUsdKwh = 0;
      let lcoeSolarUahKwh = 0;
      if (solarBal.totalSolarKwh > 0 && solarCapexTotal > 0) {
        let pvCostsUsd = solarCapexTotal;
        let pvGenKwh = 0;
        for (let yr = 1; yr <= 10; yr++) {
          const df = Math.pow(1 + disc, yr);
          pvCostsUsd += solarOpexAnnualUsd / df;
          pvGenKwh += (solarBal.totalSolarKwh * Math.pow(1 - 0.005, yr - 1)) / df;
        }
        lcoeSolarUsdKwh = pvGenKwh > 0 ? pvCostsUsd / pvGenKwh : 0;
        lcoeSolarUahKwh = lcoeSolarUsdKwh * rateToUah;
      }

      if (state.projectConfigMode === "solar") {
        const linearCost = state.linearConnectionCost || 0;
        const totalProjectCapex = solarCapexTotal + linearCost;
        const solarDirectBenefitUah = sim.solarDirectBenefitUah;
        const solarDirectBenefitUsd = rateToUah > 0 ? solarDirectBenefitUah / rateToUah : 0;
        const annualNetProfitUsd = Math.max(0, solarDirectBenefitUsd - solarOpexAnnualUsd);
        const annualNetProfitUah = annualNetProfitUsd * rateToUah;
        const simplePaybackYears = (totalProjectCapex > 0 && annualNetProfitUsd > 0) ? (totalProjectCapex / annualNetProfitUsd) : Infinity;
        const roiPct = totalProjectCapex > 0 ? (annualNetProfitUsd / totalProjectCapex) * 100 : 0;

        let cum = -totalProjectCapex;
        let paybackWithDegrad = Infinity;
        let npv = -totalProjectCapex;
        const cashFlows = [-totalProjectCapex];
        const cumulativeCf = [-totalProjectCapex];
        for (let yr = 1; yr <= 10; yr++) {
          const yrBenefit = solarDirectBenefitUsd * Math.pow(1 - 0.005, yr - 1);
          const yrNet = yrBenefit - solarOpexAnnualUsd;
          cashFlows.push(yrNet);
          const prevCum = cum;
          cum += yrNet;
          cumulativeCf.push(cum);
          if (prevCum < 0 && cum >= 0 && paybackWithDegrad === Infinity && yrNet > 0) {
            paybackWithDegrad = (yr - 1) + (Math.abs(prevCum) / yrNet);
          }
          npv += yrNet / Math.pow(1 + disc, yr);
        }
        const irrPct = computeIRR(cashFlows);

        return {
          pChargeMw: 0,
          pDischargeMw: 0,
          inverterExportUtilPct: 0,
          energyChargeMwh: 0,
          energyDischargeMwh: 0,
          chargeHoursNeeded: 0,
          dischargeHoursNeeded: 0,
          avgBuyPriceUah: 0,
          avgSellPriceUah: 0,
          dailyProfitUah: solarDirectBenefitUah / 365,
          annualGrossProfitUsd: solarDirectBenefitUsd,
          annualNetProfitUsd,
          annualNetProfitUah,
          monthlyNetProfitUsd: annualNetProfitUsd / 12,
          monthlyNetProfitUah: annualNetProfitUah / 12,
          simplePaybackYears,
          paybackWithDegrad,
          roiPct,
          irrPct,
          npv,
          lcoeSolarUsdKwh,
          lcoeSolarUahKwh,
          lcosBessUsdKwh: 0,
          lcosBessUahKwh: 0,
          selfConsumptionSharePct: sim.selfConsumptionSharePct,
          energyAutonomyPct: sim.energyAutonomyPct,
          cumulativeCf,
          chargeAllocation: new Array(24).fill(0),
          dischargeAllocation: new Array(24).fill(0),
          solarBal,
          sim8760: sim,
          legacyComparison: legacy,
          hasSolarCapex: true,
          solarCapexTotal,
          totalProjectCapex,
          bessNetProfitUsd: 0,
          bessNetProfitUah: 0,
          bessPaybackYears: Infinity,
          solarDirectBenefitUsd,
          solarDirectBenefitUah,
          hist2025: {
            monthGrossUah: sim.monthGrossUah,
            quarterGrossUah: sim.quarterGrossUah,
            quarterProfDays: [92, 90, 91, 92],
            fullYearGrossUah: solarDirectBenefitUah,
            fullYearProfDays: 365,
            fullYearNetUsd: annualNetProfitUsd,
            fullYearPayback: simplePaybackYears,
            full2025GrossUah: solarDirectBenefitUah,
            full2025ProfDays: 365,
            full2025NetUsd: annualNetProfitUsd,
            full2025Payback: simplePaybackYears,
            q4AnnualizedGrossUah: 0, q4NetUsd: 0, q4Payback: Infinity,
            q1AnnualizedGrossUah: 0, q1NetUsd: 0, q1Payback: Infinity,
            q2AnnualizedGrossUah: 0, q2NetUsd: 0, q2Payback: Infinity,
            q3AnnualizedGrossUah: 0, q3NetUsd: 0, q3Payback: Infinity
          }
        };
      }

      // BESS Only or Hybrid SES + BESS Mode (100% driven by 8,760-hour simulation)
      const pChargeMw = sim.pChargeMw;
      const pDischargeMw = sim.pDischargeMw;
      const inverterExportUtilPct = cfg.pMw > 0 ? (pDischargeMw / cfg.pMw) * 100 : 0;

      const dod = (state.dodPct || 90) / 100;
      const rte = (state.rtePct || 86) / 100;
      const cycles = Math.max(0.1, state.cyclesPerDay || 1.0);
      const energyChargeMwh = cfg.eMwh * dod * cycles;
      const energyDischargeMwh = energyChargeMwh * rte;
      const chargeHoursNeeded = pChargeMw > 0 ? energyChargeMwh / pChargeMw : 0;
      const dischargeHoursNeeded = pDischargeMw > 0 ? energyDischargeMwh / pDischargeMw : 0;

      const fullYearGrossUah = sim.bessGrossAnnualUah;
      const fullYearProfDays = sim.fullYearProfDays;
      const avgBuyPriceUah = sim.avgBuyPriceUah;
      const avgSellPriceUah = sim.avgSellPriceUah;
      const dailyProfitUah = fullYearGrossUah / Math.max(1, fullYearProfDays);

      const quarterGrossUah = sim.quarterGrossUah;
      const quarterProfDays = sim.quarterProfDays;
      const q4AnnualizedGrossUah = (quarterGrossUah[0] / 92) * 365;
      const q1AnnualizedGrossUah = (quarterGrossUah[1] / 90) * 365;
      const q2AnnualizedGrossUah = (quarterGrossUah[2] / 91) * 365;
      const q3AnnualizedGrossUah = (quarterGrossUah[3] / 92) * 365;

      const linearCost = state.linearConnectionCost || 0;
      const hasSolarCapex = state.hasSolar && state.projectConfigMode !== "bess" && (state.solarCapexPerKw > 0);
      const totalProjectCapex = cfg.capexTotal + (hasSolarCapex ? solarCapexTotal : 0) + linearCost;

      const solarDirectBenefitUah = state.hasSolar && state.projectConfigMode !== "bess" ? sim.solarDirectBenefitUah : 0;
      const solarDirectBenefitUsd = rateToUah > 0 ? solarDirectBenefitUah / rateToUah : 0;

      const bessGrossProfitUsd = rateToUah > 0 ? fullYearGrossUah / rateToUah : 0;
      const bessNetProfitUsd = bessGrossProfitUsd - cfg.opexAnnual;
      const bessNetProfitUah = bessNetProfitUsd * rateToUah;
      const bessPaybackYears = bessNetProfitUsd > 0 ? (cfg.capexTotal + linearCost) / bessNetProfitUsd : Infinity;

      const annualGrossProfitUsd = hasSolarCapex ? (bessGrossProfitUsd + solarDirectBenefitUsd) : bessGrossProfitUsd;
      const annualNetProfitUsd = hasSolarCapex ? (bessNetProfitUsd + solarDirectBenefitUsd - solarOpexAnnualUsd) : bessNetProfitUsd;
      const annualNetProfitUah = annualNetProfitUsd * rateToUah;

      const simplePaybackYears = hasSolarCapex
        ? (annualNetProfitUsd > 0 ? totalProjectCapex / annualNetProfitUsd : Infinity)
        : bessPaybackYears;

      const roiPct = hasSolarCapex
        ? (totalProjectCapex > 0 ? (annualNetProfitUsd / totalProjectCapex) * 100 : 0)
        : (cfg.capexTotal > 0 ? (bessNetProfitUsd / cfg.capexTotal) * 100 : 0);

      const q4NetUsd = (rateToUah > 0 ? q4AnnualizedGrossUah / rateToUah : 0) - cfg.opexAnnual + (hasSolarCapex ? (solarDirectBenefitUsd - solarOpexAnnualUsd) : 0);
      const q1NetUsd = (rateToUah > 0 ? q1AnnualizedGrossUah / rateToUah : 0) - cfg.opexAnnual + (hasSolarCapex ? (solarDirectBenefitUsd - solarOpexAnnualUsd) : 0);
      const q2NetUsd = (rateToUah > 0 ? q2AnnualizedGrossUah / rateToUah : 0) - cfg.opexAnnual + (hasSolarCapex ? (solarDirectBenefitUsd - solarOpexAnnualUsd) : 0);
      const q3NetUsd = (rateToUah > 0 ? q3AnnualizedGrossUah / rateToUah : 0) - cfg.opexAnnual + (hasSolarCapex ? (solarDirectBenefitUsd - solarOpexAnnualUsd) : 0);

      const q4Payback = q4NetUsd > 0 ? totalProjectCapex / q4NetUsd : Infinity;
      const q1Payback = q1NetUsd > 0 ? totalProjectCapex / q1NetUsd : Infinity;
      const q2Payback = q2NetUsd > 0 ? totalProjectCapex / q2NetUsd : Infinity;
      const q3Payback = q3NetUsd > 0 ? totalProjectCapex / q3NetUsd : Infinity;

      // 10-Year Cash Flow with degradation + IRR + LCOS
      const initialOutflow = hasSolarCapex ? totalProjectCapex : (cfg.capexTotal + linearCost);
      const cashFlows = [-initialOutflow];
      const cumulativeCf = [-initialOutflow];
      let cum = -initialOutflow;
      let paybackWithDegrad = Infinity;
      let npv = -initialOutflow;

      let pvBessCostsUsd = cfg.capexTotal;
      let pvBessDischargedKwh = 0;
      const annualDischargedKwh = sim.totalBessDischargedMwh * 1000;
      const annualGridChCostUsd = rateToUah > 0
        ? (sim.scenarioComparison.costBessGridChargeEnergyUah + sim.scenarioComparison.costBessGridChargeTariffUah) / rateToUah
        : 0;

      for (let yr = 1; yr <= 10; yr++) {
        const capFactor = Math.pow(1 - deg, yr - 1);
        const df = Math.pow(1 + disc, yr);
        const bessYrNet = (bessGrossProfitUsd * capFactor) - cfg.opexAnnual;
        const solarYrNet = hasSolarCapex ? ((solarDirectBenefitUsd * Math.pow(1 - 0.005, yr - 1)) - solarOpexAnnualUsd) : 0;
        const yrNetUsd = bessYrNet + solarYrNet;

        cashFlows.push(yrNetUsd);
        const prevCum = cum;
        cum += yrNetUsd;
        cumulativeCf.push(cum);

        if (prevCum < 0 && cum >= 0 && paybackWithDegrad === Infinity && yrNetUsd > 0) {
          paybackWithDegrad = (yr - 1) + (Math.abs(prevCum) / yrNetUsd);
        }
        npv += yrNetUsd / df;

        pvBessCostsUsd += (cfg.opexAnnual + annualGridChCostUsd * capFactor) / df;
        pvBessDischargedKwh += (annualDischargedKwh * capFactor) / df;
      }

      const irrPct = computeIRR(cashFlows);
      const lcosBessUsdKwh = pvBessDischargedKwh > 0 ? pvBessCostsUsd / pvBessDischargedKwh : 0;
      const lcosBessUahKwh = lcosBessUsdKwh * rateToUah;

      return {
        pChargeMw,
        pDischargeMw,
        inverterExportUtilPct,
        energyChargeMwh,
        energyDischargeMwh,
        chargeHoursNeeded,
        dischargeHoursNeeded,
        avgBuyPriceUah,
        avgSellPriceUah,
        dailyProfitUah,
        annualGrossProfitUsd,
        annualNetProfitUsd,
        annualNetProfitUah,
        monthlyNetProfitUsd: annualNetProfitUsd / 12,
        monthlyNetProfitUah: annualNetProfitUah / 12,
        simplePaybackYears,
        paybackWithDegrad,
        roiPct,
        irrPct,
        npv,
        lcoeSolarUsdKwh,
        lcoeSolarUahKwh,
        lcosBessUsdKwh,
        lcosBessUahKwh,
        selfConsumptionSharePct: sim.selfConsumptionSharePct,
        energyAutonomyPct: sim.energyAutonomyPct,
        cumulativeCf,
        chargeAllocation: sim.avg24ChargeAllocation,
        gridChargeAllocation: sim.avg24GridChargeAllocation,
        solarChargeAllocation: sim.avg24SolarChargeAllocation,
        dischargeAllocation: sim.avg24DischargeAllocation,
        solarBal,
        sim8760: sim,
        legacyComparison: legacy,
        hasSolarCapex,
        solarCapexTotal,
        totalProjectCapex,
        bessNetProfitUsd,
        bessNetProfitUah,
        bessPaybackYears,
        solarDirectBenefitUsd,
        solarDirectBenefitUah,
        hist2025: {
          monthGrossUah: sim.monthGrossUah,
          quarterGrossUah,
          quarterProfDays,
          fullYearGrossUah,
          fullYearProfDays,
          fullYearNetUsd: annualNetProfitUsd,
          fullYearPayback: simplePaybackYears,
          full2025GrossUah: fullYearGrossUah,
          full2025ProfDays: fullYearProfDays,
          full2025NetUsd: annualNetProfitUsd,
          full2025Payback: simplePaybackYears,
          q4AnnualizedGrossUah, q4NetUsd, q4Payback,
          q1AnnualizedGrossUah, q1NetUsd, q1Payback,
          q2AnnualizedGrossUah, q2NetUsd, q2Payback,
          q3AnnualizedGrossUah, q3NetUsd, q3Payback
        }
      };
    }



/**
 * Головна серверна функція розрахунку всього проєкту за переданим станом (statePayload)
 */
function executeServerCalculation(incomingState = {}) {
  const merged = JSON.parse(JSON.stringify(DEFAULT_STATE));
  if (incomingState && typeof incomingState === "object") {
    Object.keys(incomingState).forEach((k) => {
      if (incomingState[k] !== undefined) {
        merged[k] = incomingState[k];
      }
    });
  }
  if (!merged.bessSolarPriority) merged.bessSolarPriority = "default_surplus";
  state = merged;
  if (typeof _hourlySimCache !== "undefined" && _hourlySimCache && _hourlySimCache.clear) {
    _hourlySimCache.clear();
  }

  const stationCount = Math.min(8, Math.max(1, parseInt(state.stationCount, 10) || 3));
  const activeConfigs = (state.configs || DEFAULT_CONFIG_TEMPLATES).slice(0, stationCount);
  const activeResults = activeConfigs.map((cfg) => evaluateConfig(cfg));

  const focusIdx = Math.min(state.chartFocusIdx || 0, Math.max(0, activeConfigs.length - 1));
  const focusCfg = activeConfigs[focusIdx] || activeConfigs[0];
  const focusRes = activeResults[focusIdx] || activeResults[0];
  const mode = state.projectConfigMode || (state.hasSolar && state.hasBess ? "solar_bess" : state.hasSolar ? "solar" : "bess");
  const isSolarOnly = (mode === "solar" || !state.hasBess);
  const focusBal = isSolarOnly ? computeSolarAndLoadBalance(null) : (focusRes.solarBal || computeSolarAndLoadBalance(focusCfg));

  let bestPaybackIdx = 0;
  let maxProfitIdx = 0;
  for (let i = 1; i < activeResults.length; i++) {
    if (activeResults[i].simplePaybackYears < activeResults[bestPaybackIdx].simplePaybackYears) bestPaybackIdx = i;
    if (activeResults[i].annualNetProfitUsd > activeResults[maxProfitIdx].annualNetProfitUsd) maxProfitIdx = i;
  }

  const currMeta = getCurrencyMeta();
  const docScale = (state.priceScale || 100) / 100;
  const hourlyRdn = (state.baseHours || []).map((v) => Math.round(v * docScale));

  return {
    status: "ok",
    mode: mode,
    currency: currMeta,
    stationCount: stationCount,
    bestPaybackIdx: bestPaybackIdx,
    maxProfitIdx: maxProfitIdx,
    hourlyRdn24: hourlyRdn,
    summaryMetrics: {
      clientCompany: state.clientCompany || "",
      projectConfigMode: mode,
      connectionVoltageKv: state.connectionVoltageKv || 10,
      allowedPowerKw: state.allowedPowerKw || 2016,
      bestStationName: activeConfigs[bestPaybackIdx] ? activeConfigs[bestPaybackIdx].name : "",
      bestSimplePaybackYears: activeResults[bestPaybackIdx] ? Number(activeResults[bestPaybackIdx].simplePaybackYears.toFixed(2)) : null,
      bestAnnualNetProfitUsd: activeResults[bestPaybackIdx] ? Math.round(activeResults[bestPaybackIdx].annualNetProfitUsd) : 0,
      bestRoiPct: activeResults[bestPaybackIdx] ? Number(activeResults[bestPaybackIdx].roiPct.toFixed(1)) : 0,
      bestNpvUsd: activeResults[bestPaybackIdx] ? Math.round(activeResults[bestPaybackIdx].npv) : 0,
      totalAnnualSolarKwh: Math.round(focusBal.totalSolarKwh || 0),
      totalAnnualLoadKwh: Math.round(focusBal.totalLoadKwh || 0)
    },
    activeConfigs: activeConfigs,
    activeResults: activeResults.map((r) => ({
      pChargeMw: r.pChargeMw,
      pDischargeMw: r.pDischargeMw,
      inverterExportUtilPct: r.inverterExportUtilPct,
      chargeHoursNeeded: r.chargeHoursNeeded,
      dischargeHoursNeeded: r.dischargeHoursNeeded,
      energyChargeMwh: r.energyChargeMwh,
      energyDischargeMwh: r.energyDischargeMwh,
      avgBuyPriceUah: r.avgBuyPriceUah,
      avgSellPriceUah: r.avgSellPriceUah,
      dailyGrossProfitUah: r.dailyGrossProfitUah,
      annualGrossProfitUah: r.annualGrossProfitUah,
      annualGrossProfitUsd: r.annualGrossProfitUsd,
      annualNetProfitUah: r.annualNetProfitUah,
      annualNetProfitUsd: r.annualNetProfitUsd,
      monthlyNetProfitUah: r.monthlyNetProfitUah,
      monthlyNetProfitUsd: r.monthlyNetProfitUsd,
      totalProjectCapex: r.totalProjectCapex,
      solarCapexTotal: r.solarCapexTotal,
      hasSolarCapex: r.hasSolarCapex,
      linearConnectionCostUsd: r.linearConnectionCostUsd,
      simplePaybackYears: r.simplePaybackYears,
      paybackWithDegrad: r.paybackWithDegrad,
      roiPct: r.roiPct,
      npv: r.npv,
      irrPct: r.irrPct,
      lcoeSolarUsdKwh: r.lcoeSolarUsdKwh,
      lcosBessUsdKwh: r.lcosBessUsdKwh,
      selfConsumptionSharePct: r.selfConsumptionSharePct,
      energyAutonomyPct: r.energyAutonomyPct,
      cumulativeCf: r.cumulativeCf,
      hist2025: r.hist2025,
      dischargeAllocation: r.dischargeAllocation,
      solarChargeAllocation: r.solarChargeAllocation,
      gridChargeAllocation: r.gridChargeAllocation,
      scenarioComparison: r.sim8760 ? r.sim8760.scenarioComparison : null
    })),
    focusBalance12M: focusBal
  };
}

if (require.main === module) {
  let inputChunks = "";
  process.stdin.setEncoding("utf-8");
  process.stdin.on("data", (chunk) => { inputChunks += chunk; });
  process.stdin.on("end", () => {
    try {
      const payload = inputChunks.trim() ? JSON.parse(inputChunks) : {};
      const result = executeServerCalculation(payload);
      process.stdout.write(JSON.stringify(result));
    } catch (err) {
      process.stdout.write(JSON.stringify({ status: "error", message: err.message }));
      process.exit(1);
    }
  });
}

module.exports = { executeServerCalculation, DEFAULT_STATE, OBLENERGO_TARIFFS };